<?php
declare(strict_types=1);require __DIR__.'/app/marketplace.php';$id=marketplace_text($_GET,'id',36,true);$company=rows('SELECT id,name,public_description,public_country,public_state,public_city,marketplace_verified FROM owners WHERE id=?',[$id])[0]??null;if(!$company){http_response_code(404);$pageTitle='Company not found';}else{$pageTitle=$company['name']?:'Marketplace company';$join=" FROM marketplace_listings l JOIN equipment e ON e.id=l.asset_id JOIN owners own ON own.id=l.organization_id LEFT JOIN equipment_types t ON t.id=e.type_id LEFT JOIN marketplace_oems o ON o.id=e.marketplace_oem_id LEFT JOIN marketplace_oem_models m ON m.id=e.marketplace_oem_model_id LEFT JOIN marketplace_lease_terms lt ON lt.listing_id=l.id LEFT JOIN marketplace_sale_terms st ON st.listing_id=l.id";$listings=rows("SELECT l.*,e.name title,e.name equipment_name,e.marketplace_specifications public_specifications,t.name type_name,o.brand_name oem_name,m.model_name,own.name owner_name,own.marketplace_verified,lt.daily_rate,lt.monthly_rate,lt.currency lease_currency,st.asking_price,st.currency sale_currency{$join} WHERE l.organization_id=? AND l.listing_status='ACTIVE' AND l.visibility='PUBLIC' AND e.archived_at IS NULL ORDER BY l.published_at DESC",[$id]);}$marketActive='marketplace';require __DIR__.'/includes/marketplace-header.php';?>
<?php if(!$company):?><section class="market-empty"><h1>Company not found</h1><a href="marketplace">Return to marketplace</a></section><?php else:?><section class="company-hero"><div class="company-avatar"><?= e(strtoupper(substr($company['name']?:'C',0,1))) ?></div><div><p class="market-kicker">MARKETPLACE COMPANY <?= $company['marketplace_verified']?'· VERIFIED':'' ?></p><h1><?= e($company['name']?:'Marketplace company') ?></h1><p><?= e(implode(', ',array_filter([$company['public_city'],$company['public_state'],$company['public_country']]))) ?></p><p><?= nl2br(e($company['public_description']?:'This company has not added a public description.')) ?></p></div></section><section class="market-results company-listings"><header><div><p class="market-kicker">PUBLIC EQUIPMENT</p><h2><?= count($listings) ?> active listing<?= count($listings)===1?'':'s' ?></h2></div></header><?php if(!$listings):?><div class="market-empty"><p>No public equipment listings are active.</p></div><?php else:?><div class="market-grid"><?php foreach($listings as $listing)require __DIR__.'/includes/marketplace-card.php';?></div><?php endif;?></section><?php endif;require __DIR__.'/includes/marketplace-footer.php';?>
